import fs from 'node:fs';
const file='docs/research/venue-candidates-20261107.json',r=JSON.parse(fs.readFileSync(file,'utf8'));
const queries={'nha-trang-havana':'Havana','ha-long-wyndham-legend':'Wyndham','ha-giang-hmong-village':'Village','ta-xua-thac-may':'Mây','phu-yen-stelia':'Stelia','quy-nhon-avani':'Avani','sa-pa-viettrekking':'Viettrekking','ho-chi-minh-ba-ghien':'Cơm Tấm Ba Ghiền'};
for(const[key,q]of Object.entries(queries)){const v=r['venue-'+key];if(v.boundedHits)continue;const d=JSON.parse(fs.readFileSync('backend/src/main/resources/catalog/'+v.dest+'.json','utf8')),ref=d.references[0],lat=ref.lat,lon=ref.lon,p=new URLSearchParams({q,countrycodes:'vn',format:'jsonv2',limit:'12',bounded:'1',viewbox:`${lon-0.9},${lat+0.9},${lon+0.9},${lat-0.9}`});try{const res=await fetch('https://nominatim.openstreetmap.org/search?'+p,{headers:{'User-Agent':'WanderCatalog/0.1 (contact: https://github.com/dungv798/Wander)'},signal:AbortSignal.timeout(20000)});if(!res.ok)throw Error('HTTP '+res.status);v.boundedHits=await res.json();console.log(key,JSON.stringify(v.boundedHits.map(h=>({lat:h.lat,lon:h.lon,id:h.osm_id,type:h.type,name:h.display_name}))));}catch(e){console.log(key,e.message);}fs.writeFileSync(file,JSON.stringify(r,null,2)+'\n');await new Promise(r=>setTimeout(r,1300));}
